61	uint32_t sim_tick_ms(void)
62	{
63	    struct timespec ts;
64	
65	    clock_gettime(CLOCK_MONOTONIC, &ts);
66	    return (uint32_t)((uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u);
67	}
