69	static inline uint32_t rgb565_to_xrgb(uint16_t c)
70	{
71	    uint32_t r = (uint32_t)((c >> 11) & 0x1Fu);
72	    uint32_t g = (uint32_t)((c >> 5) & 0x3Fu);
73	    uint32_t b = (uint32_t)(c & 0x1Fu);
74	
75	    r = (r << 3) | (r >> 2);
76	    g = (g << 2) | (g >> 4);
77	    b = (b << 3) | (b >> 2);
78	    return (r << 16) | (g << 8) | b;
79	}
