81	/* 把影子缓冲的一块画到窗口（只画脏矩形，缩放用最近邻）。 */
82	static void blit_rect(int x0, int y0, int w, int h)
83	{
84	    if (s.headless || !s.dpy || !s.img) {
85	        return;
86	    }
87	
88	    const int sc = s.scale;
89	    const int iw = s.w * sc;
90	    const bool fast = (s.img->bits_per_pixel == 32);
91	
92	    for (int y = 0; y < h; y++) {
93	        const uint16_t *src = s.shadow + (size_t)(y0 + y) * (size_t)s.w + x0;
94	        for (int sy = 0; sy < sc; sy++) {
95	            int row = (y0 + y) * sc + sy;
96	            for (int x = 0; x < w; x++) {
97	                uint32_t rgb = rgb565_to_xrgb(src[x]);
98	                for (int sx = 0; sx < sc; sx++) {
99	                    int col = (x0 + x) * sc + sx;
100	                    if (fast) {
101	                        ((uint32_t *)s.img->data)[(size_t)row * (size_t)iw + col] = rgb;
102	                    } else {
103	                        XPutPixel(s.img, col, row, rgb);
104	                    }
105	                }
106	            }
107	        }
108	    }
109	    XPutImage(s.dpy, s.win, s.gc, s.img, x0 * sc, y0 * sc, x0 * sc, y0 * sc,
110	              (unsigned)w * (unsigned)sc, (unsigned)h * (unsigned)sc);
111	    XFlush(s.dpy);
112	}
