116	static void flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
117	{
118	    const int w = (int)lv_area_get_width(area);
119	    const int h = (int)lv_area_get_height(area);
120	    const uint16_t *px = (const uint16_t *)px_map;
121	
122	    for (int y = 0; y < h; y++) {
123	        memcpy(s.shadow + (size_t)(area->y1 + y) * (size_t)s.w + area->x1,
124	               px + (size_t)y * (size_t)w, (size_t)w * 2u);
125	    }
126	    blit_rect(area->x1, area->y1, w, h);
127	    lv_display_flush_ready(disp);
128	}
