139	static void key_push(uint32_t key)
140	{
141	    int next = (s.key_tail + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));
142	
143	    if (next == s.key_head) {
144	        return;
145	    }
146	    s.keys[s.key_tail] = key;
147	    s.key_tail = next;
148	}
