150	static void keypad_read(lv_indev_t *indev, lv_indev_data_t *data)
151	{
152	    (void)indev;
153	    if (s.key_head != s.key_tail) {
154	        s.last_key = s.keys[s.key_head];
155	        s.key_head = (s.key_head + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));
156	        data->state = LV_INDEV_STATE_PRESSED;
157	    } else {
158	        data->state = LV_INDEV_STATE_RELEASED;
159	    }
160	    data->key = s.last_key;
161	}
