182	int sim_display_take_raw_key(void)
183	{
184	    if (s.raw_head == s.raw_tail) {
185	        return 0;
186	    }
187	    {
188	        const char k = s.raw_keys[s.raw_head];
189	
190	        s.raw_head = (s.raw_head + 1) % (int)(sizeof(s.raw_keys) / sizeof(s.raw_keys[0]));
191	        return k;
192	    }
193	}
