195	static void key_event_push(int key, bool down)
196	{
197	    int next = (s.k2_tail + 1) % (int)(sizeof(s.keys2) / sizeof(s.keys2[0]));
198	
199	    if (next == s.k2_head) {
200	        return;
201	    }
202	    s.keys2[s.k2_tail].key = (char)key;
203	    s.keys2[s.k2_tail].down = down ? 1 : 0;
204	    s.k2_tail = next;
205	}
