207	bool sim_display_take_key_event(int *key, bool *down)
208	{
209	    if (s.k2_head == s.k2_tail) {
210	        return false;
211	    }
212	    if (key) {
213	        *key = s.keys2[s.k2_head].key;
214	    }
215	    if (down) {
216	        *down = s.keys2[s.k2_head].down != 0;
217	    }
218	    s.k2_head = (s.k2_head + 1) % (int)(sizeof(s.keys2) / sizeof(s.keys2[0]));
219	    return true;
220	}
