230	static uint32_t xkey_to_lv(KeySym ks)
231	{
232	    switch (ks) {
233	        case XK_Left:  return LV_KEY_LEFT;
234	        case XK_Right: return LV_KEY_RIGHT;
235	        case XK_Up:    return LV_KEY_UP;
236	        case XK_Down:  return LV_KEY_DOWN;
237	        case XK_Return:
238	        case XK_KP_Enter: return LV_KEY_ENTER;
239	        case XK_Escape:   return LV_KEY_ESC;
240	        case XK_BackSpace:return LV_KEY_BACKSPACE;
241	        case XK_Tab:      return LV_KEY_NEXT;
242	        case XK_Home:     return LV_KEY_HOME;
243	        case XK_End:      return LV_KEY_END;
244	        default: return 0;
245	    }
246	}
