257	/* ── 事件循环 ──────────────────────────────────────────────────── */
258	
259	bool sim_display_pump(void)
260	{
261	    if (s.headless || !s.dpy) {
262	        return !s.quit;
263	    }
264	
265	    while (XPending(s.dpy)) {
266	        XEvent ev;
267	
268	        XNextEvent(s.dpy, &ev);
269	        switch (ev.type) {
270	            case Expose:
271	                if (ev.xexpose.count == 0) {
272	                    blit_rect(0, 0, s.w, s.h);
273	                }
274	                break;
275	            case MotionNotify:
276	                s.mx = ev.xmotion.x / s.scale;
277	                s.my = ev.xmotion.y / s.scale;
278	                if (s.mx < 0) s.mx = 0;
279	                if (s.my < 0) s.my = 0;
280	                if (s.mx > s.w - 1) s.mx = s.w - 1;
281	                if (s.my > s.h - 1) s.my = s.h - 1;
282	                break;
283	            case ButtonPress:
284	                if (ev.xbutton.button == Button1) {
285	                    s.pressed = true;
286	                } else if (ev.xbutton.button == Button4) {
287	                    s.wheel++;      /* 滚轮上 = 放大 */
288	                } else if (ev.xbutton.button == Button5) {
289	                    s.wheel--;      /* 滚轮下 = 缩小 */
290	                }
291	                break;
292	            case ButtonRelease:
293	                if (ev.xbutton.button == Button1) {
294	                    s.pressed = false;
295	                }
296	                break;
297	            case KeyPress: {
298	                KeySym ks = XLookupKeysym(&ev.xkey, 0);
299	                uint32_t key = xkey_to_lv(ks);
300	
301	                if (key) {
302	                    key_push(key);
303	                }
304	                /* 板端两键：1 = KEY1，2 = KEY2（按下沿）。 */
305	                if (ks == XK_1 || ks == XK_2) {
306	                    const int n = (ks == XK_1) ? 1 : 2;
307	
308	                    if (!s.key_down[n]) {
309	                        s.key_down[n] = true;
310	                        key_event_push(n, true);
311	                    }
312	                }
313	                /* `vmap` 场景的快捷键（其它场景不轮询，等于不存在）。 */
314	                switch (ks) {
315	                    case XK_1: raw_key_push('1'); break;
316	                    case XK_2: raw_key_push('2'); break;
317	                    case XK_3: raw_key_push('3'); break;
318	                    case XK_r: raw_key_push('r'); break;
319	                    case XK_f: raw_key_push('f'); break;
320	                    case XK_i: raw_key_push('i'); break;
321	                    case XK_c: raw_key_push('c'); break;
322	                    case XK_plus: case XK_equal: case XK_KP_Add:
323	                        raw_key_push('+');
324	                        break;
325	                    case XK_minus: case XK_KP_Subtract:
326	                        raw_key_push('-');
327	                        break;
328	                    default:
329	                        break;
330	                }
331	                break;
332	            }
333	            case KeyRelease: {
334	                KeySym ks = XLookupKeysym(&ev.xkey, 0);
335	
336	                if (ks == XK_1 || ks == XK_2) {
337	                    const int n = (ks == XK_1) ? 1 : 2;
338	
339	                    if (s.key_down[n]) {
340	                        s.key_down[n] = false;
341	                        key_event_push(n, false);
342	                    }
343	                }
344	                break;
345	            }
346	            case ClientMessage:
347	                if ((Atom)ev.xclient.data.l[0] == s.wm_delete) {
348	                    s.quit = true;
349	                }
350	                break;
351	            case DestroyNotify:
352	                s.quit = true;
353	                break;
354	            default:
355	                break;
356	        }
357	    }
358	    return !s.quit;
359	}
