363	static bool shadow_alloc(void)
364	{
365	    s.shadow = calloc((size_t)s.w * (size_t)s.h, sizeof(uint16_t));
366	    if (!s.shadow) {
367	        fprintf(stderr, "sim: out of memory for shadow framebuffer\n");
368	        return false;
369	    }
370	    for (size_t i = 0; i < (size_t)s.w * (size_t)s.h; i++) {
371	        s.shadow[i] = 0xFFFF;
372	    }
373	    return true;
374	}
