376	static bool window_open(const sim_cfg_t *cfg)
377	{
378	    const int scr = DefaultScreen(s.dpy);
379	    const int win_w = s.w * s.scale;
380	    const int win_h = s.h * s.scale;
381	
382	    s.win = XCreateSimpleWindow(s.dpy, RootWindow(s.dpy, scr), 0, 0,
383	                                (unsigned)win_w, (unsigned)win_h, 0,
384	                                BlackPixel(s.dpy, scr), WhitePixel(s.dpy, scr));
385	    XStoreName(s.dpy, s.win, cfg->title ? cfg->title : "lvgl_sim");
386	
387	    XSizeHints hints;
388	    memset(&hints, 0, sizeof(hints));
389	    hints.flags = PMinSize | PMaxSize;
390	    hints.min_width = hints.max_width = win_w;
391	    hints.min_height = hints.max_height = win_h;
392	    XSetWMNormalHints(s.dpy, s.win, &hints);
393	
394	    s.wm_delete = XInternAtom(s.dpy, "WM_DELETE_WINDOW", False);
395	    XSetWMProtocols(s.dpy, s.win, &s.wm_delete, 1);
396	
397	    XSelectInput(s.dpy, s.win,
398	                 ExposureMask | ButtonPressMask | ButtonReleaseMask |
399	                 PointerMotionMask | KeyPressMask | KeyReleaseMask |
400	                 StructureNotifyMask);
401	
402	    s.gc = XCreateGC(s.dpy, s.win, 0, NULL);
403	
404	    s.img = XCreateImage(s.dpy, DefaultVisual(s.dpy, scr),
405	                         (unsigned)DefaultDepth(s.dpy, scr), ZPixmap, 0, NULL,
406	                         (unsigned)win_w, (unsigned)win_h, 32, 0);
407	    if (!s.img) {
408	        fprintf(stderr, "sim: XCreateImage failed\n");
409	        return false;
410	    }
411	    s.img->data = calloc((size_t)s.img->bytes_per_line, (size_t)win_h);
412	    if (!s.img->data) {
413	        fprintf(stderr, "sim: out of memory for XImage\n");
414	        return false;
415	    }
416	
417	    XMapWindow(s.dpy, s.win);
418	    XFlush(s.dpy);
419	
420	    if (s.img->bits_per_pixel != 32) {
421	        fprintf(stderr, "sim: warning: X server is %d bpp, using slow XPutPixel path\n",
422	                s.img->bits_per_pixel);
423	    }
424	    return true;
425	}
426	
427	bool sim_display_init(const sim_cfg_t *cfg)
428	{
429	    s.w = cfg->width > 0 ? cfg->width : 240;
430	    s.h = cfg->height > 0 ? cfg->height : 400;
431	    s.scale = cfg->scale > 0 ? cfg->scale : 2;
432	    s.headless = cfg->headless;
433	    s.quit = false;
434	
435	    if (!shadow_alloc()) {
436	        return false;
437	    }
438	    if (s.headless) {
439	        return true;
440	    }
441	
442	    s.dpy = XOpenDisplay(NULL);
443	    if (!s.dpy) {
444	        fprintf(stderr, "sim: cannot open X display; use --headless --shot out.png\n");
445	        return false;
446	    }
447	    /* 按住键不要生成 X 层的 KeyRelease 抖动：长按判定只认真正的抬起。 */
448	    {
449	        Bool supported = False;
450	
451	        XkbSetDetectableAutoRepeat(s.dpy, True, &supported);
452	    }
453	    return window_open(cfg);
454	}
