456	void sim_lvgl_bind(void)
457	{
458	    /* 两个 1/10 屏的局部缓冲：和设备的渲染模式一致，刷新时只送脏矩形 */
459	    const uint32_t stride = (uint32_t)s.w;
460	    const uint32_t lines = 40;
461	    const uint32_t bytes = stride * lines * 2u;
462	    void *buf1 = lv_malloc(bytes);
463	    void *buf2 = lv_malloc(bytes);
464	
465	    lv_display_t *disp = lv_display_create(s.w, s.h);
466	
467	    lv_display_set_flush_cb(disp, flush_cb);
468	    lv_display_set_buffers(disp, buf1, buf2, bytes, LV_DISPLAY_RENDER_MODE_PARTIAL);
469	    lv_display_set_default(disp);
470	
471	    s.indev_ptr = lv_indev_create();
472	    lv_indev_set_type(s.indev_ptr, LV_INDEV_TYPE_POINTER);
473	    lv_indev_set_read_cb(s.indev_ptr, pointer_read);
474	
475	    s.indev_key = lv_indev_create();
476	    lv_indev_set_type(s.indev_key, LV_INDEV_TYPE_KEYPAD);
477	    lv_indev_set_read_cb(s.indev_key, keypad_read);
478	    lv_indev_set_group(s.indev_key, sim_input_group());
479	}
