481	const uint16_t *sim_display_shadow(int *w, int *h)
482	{
483	    if (w) *w = s.w;
484	    if (h) *h = s.h;
485	    return s.shadow;
486	}
487	
488	void sim_display_shutdown(void)
489	{
490	    if (s.img) {
491	        /* XDestroyImage 会 free(data) */
492	        XDestroyImage(s.img);
493	        s.img = NULL;
494	    }
495	    if (s.gc && s.dpy) {
496	        XFreeGC(s.dpy, s.gc);
497	        s.gc = NULL;
498	    }
499	    if (s.win && s.dpy) {
500	        XDestroyWindow(s.dpy, s.win);
501	        s.win = 0;
502	    }
503	    if (s.dpy) {
504	        XCloseDisplay(s.dpy);
505	        s.dpy = NULL;
506	    }
507	    free(s.shadow);
508	    s.shadow = NULL;
509	}
