/* 前向声明 */
static void rebuild(void);
static void go_back(void);

static void do_short(int key)
{
    if (s_screen == SCR_SHUTDOWN) {
        if (s_power_phase == 0) {
            if (key == 1) {
                s_power_phase = 1;
                s_power_ticks = 0;
                rebuild();
            } else {
                s_screen = SCR_POWER;
                s_busy = false;
                rebuild();
            }
        } else if (s_power_phase == 2 && key == 1 && s_power_ticks >= 2) {
            s_screen = SCR_DIAL;
            s_power_phase = 0;
            s_busy = false;
            rebuild();
        }
        return;
    }
    if (s_screen == SCR_RIDE && s_end_confirm) {
        if (key == 1) {
            s_end_confirm = false;
            ride_finish();
            s_screen = SCR_DIAL;
            s_busy = false;
            rebuild();
        } else {
            s_end_confirm = false;
            rebuild();
        }
        return;
    }
    if (key == 1) {
        if (screen_is_setlist(s_screen)) {
            setl_move(1);
            return;
        }
        switch (s_screen) {
            case SCR_DIAL: dial_rotate_next(); break;
            case SCR_RIDE:
                s_ride_page = (s_ride_page + 1) % 3;
                ride_page_types();
                ride_refresh();
                break;
            case SCR_NAV:
                /* 导航页 KEY1 短：路线来源（GPX / 坐标点 / 常用点）；
                 * KEY1 长：导航中 → 本次导航；未导航 → 海拔详情。 */
                s_sub_sel = 0;
                s_screen = SCR_ROUTE_SRC;
                s_busy = false;
                rebuild();
                break;
            case SCR_RECORD:
                if (s_rec_sel + 1 < (s_rec_n < 4 ? s_rec_n : 4)) {
                    s_rec_sel++;
                    rec_sel_move(true);
                    rec_rows();
                }
                break;
            case SCR_ABOUT:
                s_about_sel = (s_about_sel + 1) % 5;
                about_focus_apply();
                break;
            default:
                break;
        }
    } else {
        go_back();
    }
}

static void ui_tick(lv_timer_t *t)
{
    (void)t;
    for (;;) {
        int key = 0;
        bool down = false;

        if (!sim_display_take_key_event(&key, &down)) {
            break;
        }
        s_idle_s = 0;
        if (s_screen == SCR_IDLE) {
            if (down) {
                s_screen = s_idle_return;
                s_busy = false;
                rebuild();
            }
            continue;
        }
        if (s_busy) {
            const bool dial_rot =
                (s_screen == SCR_DIAL && s_tr_anim == NULL && s_rot_anim != NULL);

            if (!(dial_rot && key == 1)) {
                continue;
            }
        }
        if (down) {
            if (LP.active) {
                continue;
            }
            if ((key == 1 && screen_has_lp1()) ||
                (key == 2 && screen_has_lp2())) {
                lp_begin(key);
            } else {
                do_short(key);
            }
        } else {
            if (LP.active && LP.key == key) {
                const uint32_t held = lv_tick_get() - LP.t0;

                if (held < 160) {
                    LP.active = false;
                    lp_ui_clear();
                    hint_clear();
                    if (s_screen == SCR_DIAL) {
                        dial_content(s_mode);
                    }
                    do_short(key);
                } else {
                    lp_cancel();
                }
            }
        }
    }
    lp_tick();
    if (s_toast_until != 0 && lv_tick_get() > s_toast_until) {
        s_toast_until = 0;
        if (!LP.active) {
            hint_clear();
        }
    }
    tour_tick();
}

