typedef enum {
    LP_NONE = 0,
    LP_ENTER,      /* 盘面：进入选中模式 */
    LP_ACTIVATE,   /* 设置列表：进入子页 / 循环当前值 */
    LP_PAUSE,      /* 骑行：暂停 / 继续 */
    LP_END_RIDE,   /* 骑行：长按 2 s 结束（弹确认） */
    LP_NAV_CTRL,   /* 导航：本次导航 / 海拔 */
    LP_GRADE_ZERO, /* 坡度校准：归零 */
    LP_TOGGLE_RIDE /* 盘面 KEY2：开始骑行 */
} lp_target_t;

static struct {
    bool active;
    int key;
    uint32_t t0;
    uint32_t dur;
    int pct;
    lp_target_t target;
    lv_obj_t *bar;
    lv_obj_t *track;
    lv_obj_t *arc;
} LP;

static lv_timer_t *s_ui_timer;
static lv_timer_t *s_data_timer;

/** 设置列表页（KEY1 长 = 激活当前行）。 */
static bool screen_is_setlist(scr_t s)
{
    switch (s) {
        case SCR_SETTINGS:
        case SCR_DISPLAY:
        case SCR_UNITS:
        case SCR_NAV_SET:
        case SCR_SENSOR:
        case SCR_SENSOR_SCAN:
        case SCR_BLUETOOTH:
        case SCR_INBOX:
        case SCR_REC_SET:
        case SCR_POWER:
        case SCR_USB:
        case SCR_ROUTE_SRC:
        case SCR_NAV_LIVE:
            return true;
        default:
            return false;
    }
}

static bool screen_has_lp1(void)
{
    return s_screen == SCR_DIAL || s_screen == SCR_RIDE ||
           s_screen == SCR_NAV || s_screen == SCR_GRADECAL ||
           screen_is_setlist(s_screen);
}

static bool screen_has_lp2(void)
{
    return s_screen == SCR_DIAL || s_screen == SCR_RIDE;
}

static void lp_ui_clear(void)
{
    if (LP.bar != NULL) {
        lv_obj_delete(LP.bar);
        LP.bar = NULL;
    }
    if (LP.track != NULL) {
        lv_obj_delete(LP.track);
        LP.track = NULL;
    }
    if (LP.arc != NULL) {
        lv_obj_delete(LP.arc);
        LP.arc = NULL;
    }
}

static bool lp_uses_hub(void)
{
    return s_screen == SCR_DIAL &&
           (LP.target == LP_ENTER || LP.target == LP_TOGGLE_RIDE);
}

static const char *lp_verb(void)
{
    switch (LP.target) {
        case LP_ENTER:
            return mode_name(s_mode);
        case LP_ACTIVATE:
            if (SL.sel >= 0 && SL.sel < SL.nrow) {
                const set_item_t *it = &SL.items[SL.item_of_row[SL.sel]];

                if (it->act >= SA_ENTER_DISPLAY && it->act <= SA_ENTER_SCAN) {
                    return "进入";
                }
                return "调节";
            }
            return "调节";
        case LP_PAUSE:
            if (!R.active) {
                return "开始骑行";
            }
            return R.paused ? "继续" : "暂停";
        case LP_END_RIDE:
            return "结束骑行";
        case LP_NAV_CTRL:
            return s_nav_active ? "本次导航" : "海拔";
        case LP_GRADE_ZERO:
            return "归零";
        case LP_TOGGLE_RIDE:
            return R.active ? "进入骑行" : "开始骑行";
        default:
            return "";
    }
}

static void lp_sync_text(void)
{
    char buf[96];

    if (lp_uses_hub()) {
        return;   /* 盘面把进度写在盘心，不用底部提示 */
    }
    snprintf(buf, sizeof(buf), "长按 %s · %d%% · 松手取消", lp_verb(), LP.pct);
    hint_set(buf);
}

static void lp_update_ui(void)
{
    if (lp_uses_hub()) {
        if (LP.arc != NULL) {
            lv_arc_set_value(LP.arc, LP.pct);
        }
        if (UD.value != NULL) {
            char buf[8];

            snprintf(buf, sizeof(buf), "%d%%", LP.pct);
            lv_label_set_text(UD.value, buf);
            hub_value_layout();
        }
        return;
    }
    if (LP.bar != NULL) {
        lv_obj_set_width(LP.bar, LP.pct * 192 / 100);
    }
    lp_sync_text();
}

static void lp_cancel_done(lv_anim_t *a)
{
    (void)a;
    lp_ui_clear();
    if (s_screen == SCR_DIAL && UD.value != NULL) {
        if (UD.unit != NULL) {
            lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
        }
        dial_content(s_mode);
    }
    hint_clear();
}

static void lp_fade_exec(void *var, int32_t v)
{
    (void)var;
    if (LP.arc != NULL) {
        lv_arc_set_value(LP.arc, (int)v);
    }
    if (LP.track != NULL) {
        lv_obj_set_style_arc_opa(LP.track, (lv_opa_t)(255 * v / 100), 0);
    }
}

static void lp_cancel(void)
{
    /* ANIMATION #6：120ms ease-out 进度回到 0。 */
    lv_anim_t a;
    const int start = LP.pct;

    LP.active = false;
    if (lp_uses_hub() && LP.arc != NULL) {
        lv_anim_init(&a);
        lv_anim_set_var(&a, LP.arc);
        lv_anim_set_values(&a, start, 0);
        lv_anim_set_duration(&a, 120);
        lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
        lv_anim_set_exec_cb(&a, lp_fade_exec);
        lv_anim_set_ready_cb(&a, lp_cancel_done);
        lv_anim_start(&a);
    } else {
        lp_cancel_done(NULL);
    }
}

static void lp_start_ui(void)
{
    if (lp_uses_hub()) {
        const uint32_t col = (LP.target == LP_TOGGLE_RIDE)
                                 ? C_DEEP[M_RECORD] : C_DEEP[s_mode];

        LP.track = RING(s_scr, UD.cx, UD.cy, UD.d, 4, P_TRACK);
        LP.arc = ARC(s_scr, UD.cx, UD.cy, UD.d, 4, 135, 270, col, true,
                     LV_OPA_COVER);
        lv_arc_set_value(LP.arc, 0);
        if (UD.desc != NULL) {
            lv_label_set_text(UD.desc,
                              (LP.target == LP_TOGGLE_RIDE)
                                  ? (R.active ? "进入骑行" : "开始骑行")
                                  : "保持按住");
        }
        if (UD.value != NULL) {
            lv_label_set_text(UD.value, "0%");
            hub_value_layout();
        }
        if (UD.unit != NULL) {
            lv_obj_add_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
        }
        if (UD.sub != NULL) {
            lv_label_set_text(UD.sub, "松手取消");
        }
    } else {
        uint32_t col = C_DEEP[M_SET];

        if (LP.target == LP_END_RIDE) {
            col = C_DEEP[M_RECORD];
        } else if (LP.target == LP_PAUSE || LP.target == LP_TOGGLE_RIDE) {
            col = C_DEEP[M_RIDE];
        } else if (LP.target == LP_NAV_CTRL) {
            col = C_DEEP[M_NAV];
        }
        LP.bar = B(s_scr, 24, 318, 0, 2, col, LV_OPA_COVER, 1);
        lp_sync_text();
    }
}

