static void lp_fire(void)
{
    lp_target_t target = LP.target;

    LP.active = false;
    lp_ui_clear();
    hint_clear();
    switch (target) {
        case LP_ENTER:
            if (UD.unit != NULL) {
                lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
            }
            enter_selected_mode();
            break;
        case LP_ACTIVATE:
            setl_activate();
            break;
        case LP_PAUSE:
            if (!R.active) {
                ride_start();
                s_screen = SCR_RIDE;
                s_busy = false;
                rebuild();
            } else {
                R.paused = !R.paused;
                R.auto_paused = false;
                R.still_s = 0;
                if (R.paused) {
                    R.speed = 0.0;
                    R.cadence = 0;
                    R.power = 0;
                    toast("已暂停");
                } else {
                    toast("继续骑行");
                }
                s_busy = false;
                rebuild();
            }
            break;
        case LP_END_RIDE:
            if (R.active) {
                s_end_confirm = true;
                s_busy = false;
                rebuild();
            }
            break;
        case LP_NAV_CTRL:
            if (s_nav_active) {
                s_sub_sel = 0;
                s_screen = SCR_NAV_LIVE;
            } else {
                s_screen = SCR_ELEVATION;
            }
            s_busy = false;
            rebuild();
            break;
        case LP_GRADE_ZERO:
            s_grade_off_x10 = -42;
            toast("坡度已归零");
            s_busy = false;
            rebuild();
            break;
        case LP_TOGGLE_RIDE:
            if (UD.unit != NULL) {
                lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
            }
            toggle_ride();
            if (s_screen == SCR_DIAL || s_screen == SCR_RIDE) {
                rebuild();
            }
            break;
        default:
            break;
    }
}

static void lp_tick(void)
{
    uint32_t dt;

    if (!LP.active) {
        return;
    }
    dt = lv_tick_get() - LP.t0;
    {
        int p = dt >= LP.dur ? 100 : (int)(dt * 100 / LP.dur);

        if (p != LP.pct) {
            LP.pct = p;
            lp_update_ui();
        }
        if (p >= 100) {
            lp_fire();
        }
    }
}

static void lp_begin(int key)
{
    LP.active = true;
    LP.key = key;
    LP.t0 = lv_tick_get();
    LP.pct = 0;
    LP.dur = 800;
    if (key == 2 && s_screen == SCR_DIAL) {
        LP.target = LP_TOGGLE_RIDE;
    } else if (key == 2 && s_screen == SCR_RIDE) {
        LP.target = LP_PAUSE;
    } else if (key == 1 && s_screen == SCR_DIAL) {
        LP.target = LP_ENTER;
    } else if (key == 1 && s_screen == SCR_RIDE) {
        LP.target = LP_END_RIDE;
        LP.dur = 2000;
    } else if (key == 1 && s_screen == SCR_NAV) {
        LP.target = LP_NAV_CTRL;
    } else if (key == 1 && s_screen == SCR_GRADECAL) {
        LP.target = LP_GRADE_ZERO;
    } else {
        LP.target = LP_ACTIVATE;
    }
    lp_start_ui();
    lp_update_ui();
}

