static scr_t back_parent(scr_t s)
{
    switch (s) {
        case SCR_SENSOR_SCAN: return SCR_SENSOR;
        case SCR_INBOX: return SCR_BLUETOOTH;
        case SCR_GRADECAL: return SCR_NAV_SET;
        case SCR_ROUTE_SRC:
        case SCR_NAV_LIVE: return SCR_NAV;
        case SCR_SHUTDOWN: return SCR_POWER;
        case SCR_IDLE: return s_idle_return;
        case SCR_DISPLAY:
        case SCR_UNITS:
        case SCR_NAV_SET:
        case SCR_SENSOR:
        case SCR_BLUETOOTH:
        case SCR_REC_SET:
        case SCR_POWER:
        case SCR_ABOUT:
        case SCR_USB:
            return SCR_SETTINGS;
        default:
            return SCR_SETTINGS;
    }
}

static void go_back(void)
