void scene_helm_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    s_scr = scr;
    s_screen = SCR_DIAL;
    rec_init();
    ride_preview_init();
    s_batt = 86;
    s_min = 14 * 60 + 32;
    s_clock_tick = 0;

    {
        const char *dir = getenv("SIM_HELM_TOUR");

        if (dir != NULL && dir[0] != '\0') {
            snprintf(s_tour_dir, sizeof(s_tour_dir), "%s", dir);
            (void)mkdir(s_tour_dir, 0755);
            s_tour_on = true;
            s_tour_frame = 0;
            s_tour_idx = 0;
            if (screen_from_env() != SCR_DIAL) {
                fprintf(stderr, "sim: SIM_HELM_TOUR ignores SIM_HELM_SCREEN\n");
            }
            printf("helm-tour: dir=%s\n", s_tour_dir);
        } else {
            s_screen = screen_from_env();
            {
                const char *sel = getenv("SIM_HELM_SEL");

                if (sel != NULL) {
                    s_set_sel = atoi(sel);
                    s_sub_sel = atoi(sel);
                    s_about_sel = atoi(sel) % 5;
                }
            }
        }
        /* 证据/演示用初始状态：都走真实的数据推进函数。 */
        {
            const char *rt = getenv("SIM_HELM_RIDE_T");

            if (rt != NULL && rt[0] != '\0') {
                int n = atoi(rt);
                const scr_t want = s_screen;

                ride_start();
                for (int i = 0; i < n; i++) {
                    ride_advance_1s();
                }
                s_screen = (want == SCR_DIAL) ? SCR_RIDE : want;
            }
        }
        /* 证据/演示用：直接钉住一个心率值（配合 FREEZE 看指针落点）。 */
        {
            const char *hr = getenv("SIM_HELM_HR");

            if (hr != NULL && hr[0] != '\0') {
                R.hr = atoi(hr);
            }
        }
        {
            const char *p = getenv("SIM_HELM_PAUSE");

            if (p != NULL && R.active) {
                if (strcmp(p, "manual") == 0) {
                    R.paused = true;
                    R.auto_paused = false;
                    R.speed = 0.0;
                    R.cadence = 0;
                    R.power = 0;
                    R.still_s = 0;
                } else if (strcmp(p, "auto") == 0) {
                    R.paused = true;
                    R.auto_paused = true;
                    R.speed = 0.0;
                    R.cadence = 0;
                    R.power = 0;
                }
            }
        }
        {
            const char *ec = getenv("SIM_HELM_END_CONFIRM");

            if (ec != NULL && ec[0] != '\0' && strcmp(ec, "0") != 0) {
                s_end_confirm = true;
            }
        }
        {
            const char *fz = getenv("SIM_HELM_FREEZE");

            s_freeze = (fz != NULL && fz[0] != '\0' && strcmp(fz, "0") != 0);
        }
        {
            const char *np = getenv("SIM_HELM_NAV_PHASE");
            const char *route = getenv("SIM_HELM_ROUTE");

            if (route != NULL && atoi(route) > 0) {
                s_nav_active = true;
                s_nav_route = atoi(route);
            }
            if (np != NULL) {
                if (strcmp(np, "yaw") == 0) {
                    s_nav_active = true;
                    s_nav_route = 1;
                    s_nav_phase = 1;
                    s_nav_phase_s = 0;
                } else if (strcmp(np, "arrive") == 0) {
                    s_nav_active = true;
                    s_nav_route = 1;
                    s_nav_phase = 2;
                    s_nav_phase_s = 0;
                } else if (strcmp(np, "live") == 0) {
                    s_nav_active = true;
                    s_nav_route = 1;
                    s_nav_phase = 0;
                }
            }
        }
        {
            const char *pw = getenv("SIM_HELM_POWER");

            if (pw != NULL) {
                s_screen = SCR_SHUTDOWN;
                s_power_mode = 0;
                s_power_phase = 0;
                s_power_ticks = 0;
                if (strcmp(pw, "progress") == 0) {
                    s_power_phase = 1;
                    s_power_ticks = 1;
                } else if (strcmp(pw, "off") == 0) {
                    s_power_phase = 2;
                    s_power_ticks = 3;
                } else if (strcmp(pw, "reboot") == 0) {
                    s_power_mode = 1;
                }
            }
        }
    }

    if (s_screen == SCR_DIAL) {
        dial_build();
        printf("helm: screen=main mode=%d\n", s_mode);
    } else {
        rebuild();
    }

    s_ui_timer = lv_timer_create(ui_tick, 16, NULL);
    s_data_timer = lv_timer_create(data_tick, 1000, NULL);
    (void)s_ui_timer;
    (void)s_data_timer;
}

