/* ── 关于页（保留原 4 行 + 蓝牙名；USB 传输入口在设置主列表）────── */
static void about_mark(lv_obj_t *p, int cx, int cy)
{
    (void)RING(p, cx, cy, 64, 2, P_INK);
    (void)d2_disc(p, cx, cy, 16, P_INK);
    for (int i = 0; i < 4; i++) {
        const int deg = 45 + i * 90;
        const double a = (double)deg * DEG2RAD;
        lv_point_precise_t pts[2];

        pts[0].x = cx + (int)lround(sin(a) * 10);
        pts[0].y = cy - (int)lround(cos(a) * 10);
        pts[1].x = cx + (int)lround(sin(a) * 30);
        pts[1].y = cy - (int)lround(cos(a) * 30);
        (void)LINE(p, pts, 2, 3, C_DEEP[i]);

            toast("已连接");
            if (s_screen == SCR_SENSOR_SCAN) {
                rebuild();
            }
        }
    }
    if (s_phone_pair_s > 0) {
        s_phone_pair_s--;
        if (s_phone_pair_s == 0) {
            s_phone_pair_s = -1;
            toast("配对超时 · 请重试");
            if (s_screen == SCR_BLUETOOTH) {
                rebuild();
            }
        } else if (s_screen == SCR_BLUETOOTH) {
            setl_refresh_values();
        }
    }

    if (s_screen == SCR_SHUTDOWN) {
        if (s_power_phase == 1) {
            s_power_ticks++;
            if (s_power_ticks >= 4) {
                s_power_phase = 2;
                s_power_ticks = 0;
                rebuild();
            } else {
                rebuild();
            }
        } else if (s_power_phase == 2) {
            s_power_ticks++;
            if (s_power_mode == 1 && s_power_ticks >= 3) {
                s_power_phase = 0;
                s_power_ticks = 0;
                s_screen = SCR_DIAL;
                s_busy = false;
                rebuild();
            }
        }
        return;
    }

    if (R.active) {
        const bool was_paused = R.paused;

        ride_advance_1s();
        if (s_screen == SCR_RIDE) {
            if (R.paused != was_paused) {
                rebuild();      /* 自动暂停/自动继续：顶部标签与颜色要换 */
            } else {
                ride_refresh();
            }
        } else if (s_screen == SCR_NAV) {
            nav_refresh();
#ifdef SIM_WITH_UI
            if (s_nav_view != NULL) {
                vmap_view_set_center(s_nav_view,
                                     s_nav_lon + R.dist_km * 0.00004,
                                     s_nav_lat);
            }
#endif
        } else if (s_screen == SCR_DIAL) {
            if (!LP.active && s_rot_anim == NULL) {
                dial_content(s_mode);
            }
            dial_status_refresh();
        }
    }

    /* 导航状态机：偏航 → 重规划 → 回到正常；到终点 → 到达横幅。 */
    if (s_nav_active) {
        s_nav_ticks++;
        if (s_nav_phase == 0 && s_nav_ticks >= 45) {
            s_nav_phase = 1;
            s_nav_phase_s = 0;
            toast("偏航 · 正在重新规划");
            if (s_screen == SCR_NAV) {
                rebuild();
            }
        } else if (s_nav_phase == 1) {
            s_nav_phase_s++;
            if (s_reroute && s_nav_phase_s >= 4) {
                s_nav_phase = 0;
                s_nav_turn = (s_nav_turn + 1) % 4;
                s_nav_ticks = 0;
                toast("已重新规划");
                if (s_screen == SCR_NAV) {
                    rebuild();
                }
            } else if (!s_reroute && s_nav_phase_s >= 6) {
                s_nav_phase = 0;
                s_nav_ticks = 0;
                if (s_screen == SCR_NAV) {
                    rebuild();
                }
            }
        }
        if (s_nav_phase != 2 && R.active &&
            (1.6 + R.dist_km) >= 10.0) {
            s_nav_phase = 2;
            toast("已到达终点");
            if (s_screen == SCR_NAV) {
                rebuild();
            }
        }
    }

    if (s_screen == SCR_IDLE) {
        s_idle_s++;
        if (s_idle_dur_l != NULL) {
            char buf[24];

            snprintf(buf, sizeof(buf), "%02d:%02d", s_idle_s / 60,
                     s_idle_s % 60);
            lv_label_set_text(s_idle_dur_l, buf);
        }
        if (s_idle_clock_l != NULL) {
            char buf[24];

            fmt_clock(s_min, buf, sizeof(buf));
            lv_label_set_text(s_idle_clock_l, buf);
        }
        return;
    }

    /* 自动锁定：按键间隔达到设置值 → 熄屏（骑行中仍按表，不熄）。 */
    if (!(R.active && R.speed >= AUTO_PAUSE_ENTER_KMH)) {
        s_idle_s++;
        if (s_lock > 0 && s_idle_s >= s_lock) {
            s_idle_return = s_screen;
            s_idle_s = 0;
            s_screen = SCR_IDLE;
            s_busy = false;
            rebuild();
        }
    } else {
        s_idle_s = 0;
    }
}

