 *
 * 与 KEY1/KEY2 的 LP 状态机分开，任何屏都可用（真长按，按按住时长判定）：
 *   短按（松手 < 800 ms）  熄屏 / 亮屏切换（SCR_IDLE，旧 helm_idle 语义）
 *   长按（按住 ≥ 800 ms）  关机确认（SCR_SHUTDOWN phase 0，旧 helm_pwr 语义）
 *   关机黑屏（phase 2）    按一下 = 开机回盘面
 *
 * 熄屏时按 ↑ 先唤醒：这次按下/抬起整对吃掉，避免抬起又被当成短按关回去。 */
#define PWR_LONG_MS 800

static struct {
    bool down;
    bool fired;
    bool ignore_up;
    uint32_t t0;
} PWR;

static bool s_keylog;   /* SIM_HELM_KEYLOG=1：每次按键/动作打一行（取证用） */

static void keylog(const char *fmt, ...)
{
    va_list ap;

    if (!s_keylog) {
        return;
    }
    printf("helm-key: ");
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    putchar('\n');
    fflush(stdout);
}

static void pwr_wake(void)
{
    if (s_screen == SCR_SHUTDOWN) {
        s_screen = SCR_DIAL;
        s_power_phase = 0;
        s_power_ticks = 0;
    } else {
        s_screen = s_idle_return;
    }
    s_idle_s = 0;
    s_busy = false;
    rebuild();
}

static void pwr_sleep(void)
{
    if (s_screen == SCR_IDLE || s_screen == SCR_SHUTDOWN) {
        return;
    }
    s_idle_return = s_screen;
    s_idle_s = 0;
    s_screen = SCR_IDLE;
    s_busy = false;
    rebuild();
}

static void pwr_shutdown_confirm(void)
{
    if (s_screen == SCR_IDLE || s_screen == SCR_SHUTDOWN) {
        return;
    }
    s_power_mode = 0;
    s_power_phase = 0;
    s_power_ticks = 0;
    s_screen = SCR_SHUTDOWN;
    s_busy = false;
    rebuild();
}

static void pwr_event(bool down)
{
    if (down) {
        if (PWR.down) {
            return;             /* 自动重复已在上游去重，这里兜底 */
        }
        if (s_screen == SCR_IDLE ||
            (s_screen == SCR_SHUTDOWN && s_power_phase == 2)) {
            pwr_wake();
            PWR.ignore_up = true;
            keylog("POWER down -> wake (%s)", SCR_NAME[s_screen]);
            return;
        }
        if (s_screen == SCR_SHUTDOWN) {
            PWR.ignore_up = true;   /* 确认/进度页：电源键不参与 */
            keylog("POWER down ignored (shutdown phase %d)", s_power_phase);
            return;
        }
        if (LP.active) {
            PWR.ignore_up = true;
            keylog("POWER down ignored (LP active)");
            return;
        }
        PWR.down = true;
        PWR.fired = false;
        PWR.t0 = lv_tick_get();
        hint_set("长按关机 · 松手熄屏");
        keylog("POWER down screen=%s", SCR_NAME[s_screen]);
        return;
    }

    if (PWR.ignore_up) {
        PWR.ignore_up = false;
        keylog("POWER up consumed (wake)");
        return;
    }
    if (!PWR.down) {
        return;
    }
    PWR.down = false;
    {
        const uint32_t held = lv_tick_get() - PWR.t0;

        hint_clear();
        if (PWR.fired) {
            PWR.fired = false;
            keylog("POWER up held=%ums (shutdown already fired)", held);
            return;
        }
        if (held >= PWR_LONG_MS) {
            keylog("POWER up held=%ums -> shutdown", held);
            pwr_shutdown_confirm();
        } else {
            keylog("POWER up held=%ums -> sleep", held);
            pwr_sleep();
        }
    }
}

static void pwr_tick(void)
{
    if (!PWR.down || PWR.fired) {
        return;
    }
    {
        const uint32_t held = lv_tick_get() - PWR.t0;

        if (held >= PWR_LONG_MS) {
            PWR.fired = true;
            hint_clear();
            keylog("POWER long held=%ums -> shutdown", held);
            pwr_shutdown_confirm();
        }
    }
}

